// --- F_GETFD / F_SETFD (File Descriptor Flags) ---
// Set Close-On-Exec flag (FD_CLOEXEC)
int flags = fcntl(fd, F_GETFD);
if (flags != -1) {
    flags |= FD_CLOEXEC;
    fcntl(fd, F_SETFD, flags);
}

// --- F_GETFL / F_SETFL (File Status Flags) ---
// Enable O_NONBLOCK
int status = fcntl(fd, F_GETFL);
status |= O_NONBLOCK;
fcntl(fd, F_SETFL, status);

// --- F_DUPFD (Duplicate FD) ---
// Duplicate fd to lowest available FD >= 10
int new_fd = fcntl(fd, F_DUPFD, 10);
// Use F_DUPFD_CLOEXEC for atomic close-on-exec setting
// int new_fd = fcntl(fd, F_DUPFD_CLOEXEC, 10);

// --- F_SETLK (Advisory Locking) ---
struct flock fl = {
    .l_type = F_WRLCK,      // F_RDLCK, F_UNLCK
    .l_whence = SEEK_SET,
    .l_start = 0,           // Byte offset
    .l_len = 0              // 0 means entire file
};
// Acquire write lock (non-blocking)
fcntl(fd, F_SETLK, &fl);

// Try blocking lock acquisition
// fcntl(fd, F_SETLKW, &fl);
